-- ─── ไทม์ไลน์ 240 รายการ ───
-- ลบของเดิมที่มาจากการนำเข้าก่อน กันซ้ำเวลาวางไฟล์นี้รอบสอง
delete from public.events where src = 'import';
;

-- ─── ตรวจผล ───
select 'ซับ' as "ตาราง", count(*) as "จำนวน" from public.vendors
union all select 'ทะเบียนรถ', count(*) from public.trucks
union all select 'เคส', count(*) from public.cases
union all select 'ไทม์ไลน์', count(*) from public.events;
